"""Authored replacement depth. Legacy prose is available only in the v6 archive.

The short cases here are supplied-data exercises, never claims of live execution.
"""
LESSONS = {}


def add(id, title, model, detail, facts, interpretation, task, boundary):
    assert id not in LESSONS
    LESSONS[id] = dict(title=title, model=model, detail=detail, facts=facts,
                      interpretation=interpretation, task=task, boundary=boundary)


add('terminal', 'Что оболочка передаёт ядру',
    'Оболочка разбирает строку, раскрывает переменные и запускает программу с аргументами. Она не понимает смысл этих аргументов. pwd показывает текущий каталог, ls — имена, cd меняет каталог самой оболочки, cat читает файл, less позволяет листать, man открывает справку. Относительный путь отсчитывается от текущего каталога. В less и man выходят клавишей q; у редактора свои правила выхода, которые нужно узнать до изменения файла.',
    'У процесса есть таблица файловых дескрипторов: 0 обычно вход, 1 обычный вывод, 2 ошибки. Перенаправление меняет связь номера с открытым объектом. Pipe связывает вывод одного процесса со входом другого и имеет конечную ёмкость. read() — системный вызов чтения; strace показывает такие обращения, но не внутреннюю логику приложения. /proc предоставляет представления состояния процессов. Load average включает готовые задачи и непрерываемые ожидания, поэтому не является процентом CPU.',
    'Производитель пишет архив в pipe. Читатель остановлен. CPU свободен, процесс производителя жив, новых байтов нет.',
    'Производитель может ждать свободного места в pipe. Наличие PID подтверждает существование процесса, но не продвижение работы. Сначала установи, какой ресурс он ждёт и кто должен его освободить.',
    'Нарисуй отдельно пути stdout и stderr для конвейера из двух программ. Предскажи, попадёт ли ошибка первой программы в файл, куда направлен только stdout второй.',
    'Перед изменением проверь текущий каталог, область действия и способ возврата. Наблюдение через strace может влиять на время работы; не используй его задержки как исходную производительность.')

add('one-change', 'Как выбрать проверку, которая что-то различает',
    'Жалоба «страница недоступна» не называет сломанный компонент. Раздели путь: клиент, разрешение имени, маршрут, транспортное соединение, TLS, приложение, данные. Наблюдение — измеренный факт с условиями; гипотеза — объяснение; вывод — то, что факт позволяет исключить или подтвердить. Проверка полезна, если конкурирующие гипотезы предсказывают разные результаты.',
    'Сначала зафиксируй исходное состояние, время, адрес, пользователя и точный текст ошибки. Затем меняй одну причину за опыт. Без этого успешный ответ после трёх изменений не показывает, какое было нужно. Количественная модель связывает единицы: время ответа складывается из этапов, пропускная способность ограничивается узким местом. Повторные измерения показывают разброс; один замер не задаёт распределение.',
    'С клиента TCP получает refused; на сервере в нужном сетевом пространстве нет слушателя на проверенном адресе и порте.',
    'Отказ согласуется с отсутствием слушателя, но RST мог выдать и фильтр. Сопоставление проверки клиента, сокета и журналов сужает границу. Перезапуск без сохранения фактов уничтожил бы часть объяснения.',
    'Для гипотез «неверный DNS» и «программа слушает только loopback» предложи по одной проверке и запиши ожидаемые результаты для обеих гипотез до опыта.',
    'Сначала наблюдение без изменений. Окончание ремонта требует проверки пользовательского результата и соседнего пути, а не только исчезновения сообщения об ошибке.')

add('units', 'Число без единицы ещё не измерение',
    'Байт содержит восемь бит. MB и Mbit обозначают разные величины; MiB — 2²⁰ байт, MB — 10⁶ байт. Интервал времени отличается от отметки на часах. Скорость получается делением объёма на интервал с согласованными единицами; округляй итог, сохраняя исходные значения.',
    'Для сравнения двух опытов нужны одинаковые границы: начало запроса или установления соединения, конец передачи или подтверждение записи. Среднее зависит от набора наблюдений. Отдельный медленный ответ может быть важнее среднего, если пользователь ждёт именно его.',
    'Передано 125 MB за 10 s.', 'Средняя полезная скорость — 12,5 MB/s, то есть 100 Mbit/s. Это не скорость линии: заголовки, повторные передачи и паузы сюда отдельно не включены.',
    'Пересчитай время передачи 1 GiB при полезной скорости 128 MiB/s. Укажи, какой вывод о скорости физического порта сделать нельзя.',
    'Не смешивай десятичные и двоичные единицы и не приписывай измерению точность, которой нет у часов или счётчика.')

add('lab-map', 'Какие объекты существуют в лаборатории',
    'Хост — физический компьютер с гипервизором, гость — созданная им ВМ. Proxmox объединяет управление QEMU/KVM, сетями, хранением и копиями. Linux bridge пересылает кадры между подключёнными портами; vmbr0 часто связан с физическим портом, но название само этого не гарантирует. Три моста без физических портов могут образовать три изолированных учебных сегмента. Между ними нужен отдельный маршрутизатор, если требуется IP-связность.',
    'Cloud image — подготовленный образ ОС; cloud-init задаёт параметры экземпляра. Общий исходный образ упрощает сравнение, но каждому гостю нужны собственные идентификаторы и конфигурация. Ресурсы гостя конкурируют за ресурсы хоста. Виртуальный диск лежит на конкретном хранилище; несколько дисков ВМ могут зависеть от одного физического носителя. Снимок помогает вернуться к состоянию, независимая резервная копия защищает от утраты исходного хранилища.',
    'Две ВМ подключены к разным изолированным мостам. Адреса назначены, маршрутизатора между сегментами нет.',
    'Адрес сам не создаёт путь. Сначала рисуют порты, мосты, префиксы и шлюзы; затем проверяют путь по границам. Неправильный шлюз — безопасный учебный отказ только внутри гостевой сети.',
    'Нарисуй вариант стенда на одном компьютере и вариант с отдельным коммутатором. Отметь общие питание и диск, адрес управления, место хранения копии и путь восстановления доступа.',
    'На рабочей Windows или Linux используй гостевые ресурсы; не отдавай системный диск установщику. Корпоративная сеть требует согласованного подключения. ECC, физические линии PCIe, питание и охлаждение не подтверждаются эмуляцией. Сохрани схему и изменения в инженерном репозитории.')

add('lab-setup', 'Подготовить среду, которую можно восстановить',
    'Установщик гипервизора изменяет выбранные диски. До установки нужен инвентарь накопителей с серийными номерами, сохранённые данные и проверенный путь к консоли. В прошивке проверяют поддержку и включение виртуализации, режим загрузки и пригодность оборудования. Основной стенд — выделенный хост; альтернативой для начальных опытов служит отдельная ВМ. Физические диски для расширения выбирают по интерфейсу, ёмкости, состоянию и назначению, а не по букве устройства.',
    'План адресов задаёт адрес управления, префикс, шлюз, DNS и учебные диапазоны без пересечений с существующими сетями. Статический адрес или закреплённая аренда должны обеспечивать предсказуемый вход. Сначала проверяют консоль и управление, затем гостевые сети, хранение и возврат. Перед автоматической подготовкой скачивают фиксированную версию, проверяют хеш и читают действия; изменяемая ветка не является идентификатором проверенной версии.',
    'После перезагрузки гость доступен, а адрес управления хоста неизвестен. Есть запись DHCP и локальная консоль.',
    'Восстанови фактический адрес через консоль и аренду, сверь интерфейс и мост с планом. Успешный вход в одного гостя не подтверждает управляемость гипервизора.',
    'Составь приёмку из пяти наблюдаемых результатов: доступ, гостевой ответ, идентичность диска, независимая копия, повторный запуск после отката. Для каждого назови источник доказательства.',
    'Процедура возврата должна существовать до первой поломки. Исполнитель практики разрешён только на явно выделенном госте; не регистрируй рабочий компьютер или Proxmox-хост как одноразовую ВМ.')

add('process', 'Что скрывается за PID',
    'Поток — исполняемый контекст с регистрами и стеком; потоки процесса могут разделять адресное пространство и открытые файлы. Планировщик Linux распределяет время между исполняемыми задачами. Контекстное переключение меняет выполняемую задачу, но не делает ожидающее устройство быстрее. /proc/PID содержит сведения о конкретном экземпляре процесса; доступ зависит от прав и настроек.',
    'Состояния R, S, D и Z описывают готовность, ожидания и завершение. Z — завершившийся процесс, чей статус ещё не забрал родитель; он не продолжает вычисления. D — непрерываемое ожидание, не обязательно именно диск. SIGKILL нельзя обработать обычным обработчиком, но завершение может ждать выхода из такого ожидания. Проверяют wait channel, стек и зависимый ресурс. TIME — накопленный CPU, elapsed — возраст процесса; у нескольких потоков суммарный CPU может превышать календарный интервал.',
    'Процесс прожил 120 s, накопил 3 s CPU и сейчас имеет статус S.',
    'Он большую часть интервала не занимал CPU. Текущий S не рассказывает все прошлые состояния и не доказывает исправность приложения. Нужны наблюдения во времени и проверка полезного ответа.',
    'Сравни два экземпляра одной программы с разными PID и временем старта. Какие наблюдения отличат ожидание pipe от готовности к исполнению?',
    'Не завершай процессы по совпадению одного имени. Сопоставь владельца, командную строку, метку попытки и время запуска; PID может использоваться повторно.')

add('memory', 'Адрес процесса и место хранения страницы',
    'Виртуальный адрес принадлежит адресному пространству процесса. Таблицы страниц связывают его со страницей физической памяти или указывают, что доступ требует обработки page fault. Fault может означать подгрузку файла или выделение страницы, а не аппаратную ошибку. VFS — общий интерфейс ядра к разным файловым системам; page cache хранит страницы файлов и ускоряет повторное чтение.',
    'RSS оценивает резидентные страницы процесса, виртуальный размер включает и ещё не занятую физическую память. Общие страницы нельзя бездумно складывать по всем RSS. Used включает полезные кэши; MemAvailable оценивает доступную память с учётом части освобождаемого кэша. Грязные страницы требуют записи перед освобождением. Swap переносит часть содержимого страниц, но не заменяет RAM по задержке. Давление памяти, лимит cgroup и OOM могут возникнуть при ненулевом free.',
    'После первого чтения файла свободной памяти стало меньше, второе чтение быстрее. Процесс не увеличил собственные данные.',
    'Это согласуется с page cache. Нельзя объявить утечку по одному used: нужны динамика RSS/PSS, кэша, доступной памяти и нагрузки.',
    'Объясни, почему два процесса с общими библиотеками не обязательно занимают сумму их виртуальных размеров. Предскажи эффект холодного и тёплого чтения.',
    'Не сбрасывай кэши и не вызывай OOM на рабочей машине ради опыта. Ограничения памяти проверяют внутри выделенного гостя или специально созданной группы.')

add('permissions', 'Как имя файла становится проверкой доступа',
    'Каталог связывает имя с inode, который описывает объект файловой системы. Жёсткие ссылки дают несколько имён одному inode; символическая ссылка хранит путь, который разрешается отдельно. Удаление имени не прекращает доступ через уже открытый дескриптор. Для прохода по каталогу нужен x, для списка имён — r, для изменения записей — w вместе с x; разрешение на удаление определяется прежде всего родительским каталогом.',
    'Для обычных mode bits выбирается класс владельца, иначе подходящей группы, иначе остальных; это не суммирование всех трёх классов. ACL добавляет именованные записи и маску эффективных прав. setgid на каталоге помогает наследовать группу; sticky ограничивает удаление чужих записей в общем каталоге. setuid у исполняемого файла может менять effective UID. NSS определяет источник учётных записей; /etc/passwd не хранит современные хеши паролей, локальные хеши обычно в /etc/shadow. sudo делегирует конкретные действия. Capabilities и мандатные политики добавляют проверки сверх mode bits.',
    'У журнала mode 0660 и правильная группа, но родительский каталог 0700 принадлежит другому пользователю.',
    'Процесс не может пройти по пути. Изменение режима только конечного файла не исправит доступ к каталогу.',
    'Разбери путь к заметке для владельца, участника группы и постороннего. Отдельно предскажи чтение файла, список каталога и удаление имени.',
    'Проверяй от имени пользователя службы. chmod 777 не является диагностикой; mount read-only, ACL, SELinux/AppArmor и настройки службы могут запрещать доступ даже при широких mode bits.')

add('packages', 'Пакет — управляемый набор файлов',
    'Пакет содержит файлы, метаданные, зависимости и действия установки. Репозиторий публикует версии и подписанные сведения, по которым менеджер проверяет происхождение и целостность. Доверие к подписи не доказывает отсутствие ошибок в программе. apt выбирает версии и разрешает зависимости; dpkg учитывает установленные Debian-пакеты.',
    'Исполняемый файл в PATH может происходить из пакета, локальной установки, виртуального окружения или пользовательского каталога. Поэтому сначала устанавливают фактический путь, затем владельца файла и версию. Обновление списка пакетов отличается от обновления установленной системы. Конфигурация, данные службы и кеши имеют другой жизненный цикл, чем бинарные файлы пакета.',
    'В пакете установлен один Python, но команда python3 запускает файл из домашнего каталога.',
    'Версия пакета не описывает фактически вызванную программу. Причина может быть в порядке PATH, а не в неисправной установке.',
    'Составь проверку происхождения интерпретатора и объясни, какие данные не вернутся после простой переустановки пакета приложения.',
    'Установка и удаление требуют администратора и могут запускать службы. Сначала используй наблюдение; перед обновлением сохрани конфигурацию и способ возврата.')

add('systemd', 'Описание запуска и полезная готовность',
    'Юнит — описание управляемого объекта; service управляет процессами, mount — монтированием, timer — расписанием, socket — активацией по сокету. Процессы службы объединяются в cgroup, поэтому служба не равна одному PID. Unit file и drop-in образуют эффективную конфигурацию; значения нужно смотреть у менеджера, а не только в одном файле.',
    'Requires/Wants задают зависимости, After/Before — порядок. Одного After недостаточно, чтобы запустить зависимость. network.target не обещает доступность удалённого API. Type=simple подтверждает начало процесса, а не готовность HTTP; Type=notify требует корректного уведомления программы. Restart ограничивают политикой и частотой, иначе ошибка превращается в цикл. У службы собственные User, WorkingDirectory, PATH и Environment. daemon-reload перечитывает определения; restart запускает процесс заново.',
    'Программа читает ./config.json вручную из своего каталога; служба с другим рабочим каталогом завершается с ENOENT.',
    'Файл не обязательно отсутствует на диске. Отличаются условия запуска. Явный путь или корректный WorkingDirectory устраняет эту неоднозначность.',
    'Предложи отдельные проверки: менеджер принял конфигурацию, процесс запущен, порт слушает, заметка получена. Объясни, почему таймер и socket activation требуют разных ожиданий.',
    'Не заменяй системные юниты пакета ради учебного опыта. Используй отдельное имя, сохрани drop-in и проверяй журнал и пользовательский ответ после изменения.')

add('logs', 'Событие, источник и время',
    'journald принимает сообщения ядра и пользовательских служб, добавляя поля источника. dmesg читает кольцевой буфер сообщений ядра; наличие строки в journal само по себе не делает ядро виновником. Поля unit, PID, boot ID и transport помогают связать события. После перезагрузки PID может повториться, а стеновые часы могут быть скорректированы.',
    'Порядок запуска и зависимость служб проверяются отдельно: запись «стартовала B» не означает, что A готова принимать запросы. Хранение журнала может быть постоянным или временным, с лимитами объёма и срока. Отсутствие старой строки может означать ротацию или другой boot, а не отсутствие события. Выборка по небольшому временному окну и конкретной службе уменьшает шум; секреты перед передачей отчёта удаляют.',
    'Служба падает при загрузке, а вручную стартует позже. В журнале сначала ошибка DNS, затем успешное получение адреса.',
    'Порядок согласуется с неготовой зависимостью, но требует проверки: какие адреса и resolver использовала служба? Один поздний успех не объясняет ранний отказ.',
    'Собери линию из пяти событий с источником и boot ID. Отметь наблюдение, гипотезу и недостающий факт.',
    'Сохраняй исходные строки и условия выборки. Фильтрация и перевод часового пояса не должны незаметно менять порядок исходных фактов.')

add('boot', 'На каком переходе остановилась загрузка',
    'Цепочка загрузки передаёт управление от прошивки загрузчику, ядру и ранней среде, затем основной системе. GRUB выбирает ядро, initramfs и параметры. initramfs нужен, чтобы получить доступ к корню: загрузить драйвер контроллера, собрать нужный слой хранения, открыть шифрованное устройство. Успешное меню GRUB ещё не доказывает, что новое ядро запущено.',
    'root= в командной строке ядра и записи /etc/fstab решают разные задачи. fstab описывает последующие монтирования и может породить systemd mount units; неверный UUID или обязательное недоступное устройство задерживает загрузку. В аварийной оболочке набор инструментов ограничен. Live-среда и chroot помогают работать с установленной системой, но chroot сам по себе не меняет загруженное ядро. Пересборка initramfs и установка GRUB зависят от дистрибутива, UEFI/BIOS и схемы дисков.',
    'После замены HBA прошивка видит загрузчик, ядро начинает работу, но root UUID недоступен.',
    'Граница отказа позже прошивки. Проверяют видимость контроллера и диска в ранней среде, драйвер и идентичность корня. Форматирование или переустановка загрузчика без этого не обоснованы.',
    'Раздели доказательства для четырёх стадий загрузки. После учебного исправления покажи фактическую версию работающего ядра и источник корневой файловой системы.',
    'Экспериментируй на отдельном госте с консолью и снимком. Не копируй универсальную команду восстановления GRUB на хост с неизвестной разметкой; сначала установи режим загрузки и целевые устройства.')

add('mount', 'Монтирование меняет видимое дерево',
    'Mount связывает файловую систему с точкой в дереве имён текущего mount namespace. Существующие файлы каталога под ней не удаляются, но скрываются этим представлением. Если ожидаемый диск не смонтирован, программа может записать данные в каталог на корневой файловой системе.',
    'Имя /dev/sdX непостоянно. UUID файловой системы помогает найти нужный объект, но клонирование может создать одинаковые UUID. Поэтому сопоставляют источник, тип, размер и ожидаемое содержимое. После загрузки initramfs должен обнаружить корень; остальные записи fstab применяются уже в другом контексте. Ошибка nofail допустима не для всех зависимостей: приложению всё равно нельзя писать не туда.',
    'В /data есть заметка, но findmnt показывает, что /data не является отдельной точкой монтирования.',
    'Наличие файла не подтверждает нужный носитель. Запись могла попасть на корневой диск. Перед переносом нужно остановить запись и сохранить обе версии.',
    'Предскажи, что станет видно до mount, после mount и после umount. Как проверить источник данных без удаления скрытого каталога?',
    'Не монтируй неизвестные диски поверх рабочих данных. Проверка и откат учебного образа выполняются только в выделенном госте; занятый mount сначала исследуют, а не размонтируют force.')

add('address', 'Путь кадра и путь IP-пакета',
    'Ethernet передаёт кадр между соседями второго уровня; MAC адресует интерфейс на этом участке. IPv4 адрес вместе с префиксом определяет локальную сеть. Для локального IPv4-соседа ARP выясняет MAC. Для удалённого назначения отправитель ищет маршрут и MAC следующего узла, а не удалённого сервера. Шлюз — соседний маршрутизатор, не обязательный «сервер интернета».',
    'Из подходящих маршрутов выбирается самый длинный совпадающий префикс; дополнительные правила политики могут выбирать другую таблицу. Ядро также выбирает исходный адрес. ip route get показывает решение для конкретных условий. Состояние carrier относится к линии, адрес — к интерфейсу, слушатель — к программе: один уровень не доказывает другой. Постоянная конфигурация может задаваться разными сетевыми менеджерами и cloud-init; ручная настройка не обязательно переживёт загрузку.',
    'Хост 192.0.2.10/24 отправляет пакет на 198.51.100.20 через 192.0.2.1.',
    'В первом Ethernet-кадре адрес назначения принадлежит шлюзу; IP назначения остаётся адресом сервера, если NAT ещё не применялся. Следующий маршрутизатор снова выбирает следующий участок.',
    'Нарисуй путь туда и обратно. Для каждого участка назови IP назначения и владельца MAC назначения. Где проверять ARP, если шлюз не отвечает?',
    'Не изменяй интерфейс управления хоста через удалённую сессию ради опыта. Изоляция гостевой сети и консоль должны существовать заранее.')

add('prefix', 'Префикс — правило выбора пути',
    'В IPv4 префикс /n оставляет n старших бит адреса для сети. В обычной подсети /24 меняется восемь младших бит. Побитовое AND с маской даёт адрес сети. Broadcast — адрес с единицами в битах хоста. Правило «минус два адреса» не универсально: /31 имеет специальное применение на двухточечных линиях, /32 описывает один адрес.',
    'Одинаковые адреса с разными масками могут дать разное решение о локальности. Более специфичный маршрут выигрывает у default даже при непохожем на ожидание шлюзе. CIDR позволяет описывать диапазоны разной длины; суммирование диапазонов допустимо только при правильном выравнивании и полном охвате.',
    'Для 192.0.2.130/26 сеть — 192.0.2.128, broadcast — 192.0.2.191.',
    'Блок содержит 64 адреса; обычный диапазон хостов — .129–.190. Адрес .126 находится в другом /26, хотя первые три октета совпадают.',
    'Рассчитай сеть для .130/25 и сравни решение о локальности .126. Затем объясни, почему маршрут /32 может переопределить /24.',
    'Расчёт адресов не подтверждает доступность пути. Пересечения префиксов, политика маршрутизации и обратный маршрут проверяются отдельно.')

add('tcp', 'Соединение — история обмена',
    'TCP идентифицирует соединение адресами и портами обеих сторон. SYN, SYN-ACK и ACK устанавливают состояние; наличие LISTEN — готовность сокета принимать соединения, а не доказательство успешного приложения. RST означает сброс на наблюдаемом пути; отсутствие ответа имеет другие возможные причины. FIN обозначает штатное завершение направления передачи, TIME_WAIT защищает от старых сегментов.',
    'Receive window ограничивает приём получателем, congestion window — объём отправки с учётом состояния сети. Повторные передачи и рост RTT могут снизить полезную скорость. UDP передаёт датаграммы без встроенного рукопожатия и гарантии доставки; надёжность при необходимости добавляет приложение. DHCP выдаёт параметры аренды, DNS разрешает имена — это отдельные протоколы. tcpdump показывает пакеты в точке наблюдения, ss — состояние сокетов; оба нужны для связи событий во времени.',
    'Рукопожатие завершено, затем клиент отправил запрос, но полезного ответа нет.',
    'Достижимость TCP доказана для момента рукопожатия. Причина может быть в TLS, обработчике, зависимостях или дальнейшем обмене; проверка только SYN уже не разделяет эти варианты.',
    'Для refused, повторяющегося SYN и закрытия после запроса составь разные следующие проверки. Объясни, каких гарантий нет у UDP.',
    'Захват может содержать личные данные и секреты. Ограничивай интерфейс, фильтр, объём и срок; право захвата выдаётся отдельно. Потери в захвате не всегда означают потери на линии.')

add('dns', 'Имя, ответ resolver и фактический адрес',
    'Приложение обычно обращается к системному resolver. Тот использует конфигурацию, локальные источники и DNS; ответы могут кешироваться. Авторитативный сервер хранит зону, рекурсивный resolver ищет ответ для клиента. A и AAAA задают адреса разных семейств, CNAME — другое имя, а не перенаправление HTTP. TTL ограничивает время кеширования записи, но не принуждает уже открытое соединение сменить адрес.',
    'NXDOMAIN означает отсутствие имени в полученном ответе, SERVFAIL — сбой разрешения, timeout — отсутствие своевременного ответа. Сравнение обращения по имени и по IP помогает отделить разрешение от транспорта, но HTTPS по голому IP может нарушить проверку имени сертификата. DHCP может раздать DNS, но действующая аренда не доказывает исправность resolver.',
    'По старому адресу страница работает; имя на клиенте разрешается в другой адрес.',
    'Проверяй источник ответа и TTL до очистки кешей. Подмена имени в локальной проверке позволяет проверить тот же Host/SNI, сохранив смысл запроса.',
    'Нарисуй две независимые проверки: какой адрес получил клиент и какой сервер обработал запрос. Как отличить несуществующее имя от недоступного DNS?',
    'Не меняй корпоративную зону или общий resolver ради упражнения. Используй собственную учебную зону и сохраняй исходные ответы.')

add('mtu', 'Размер пакета меняется по пути',
    'MTU интерфейса ограничивает размер пакета на данном участке. Туннель добавляет заголовки и уменьшает доступный размер внутреннего пакета. MSS TCP описывает полезную нагрузку сегмента и не равен MTU. В IPv4 фрагментация зависит от DF; в IPv6 маршрутизаторы не фрагментируют транзитный пакет. Path MTU discovery использует сообщения о слишком большом пакете; их фильтрация может создать «чёрную дыру».',
    'Успешный маленький ping не проверяет большие передачи. Учитывай размер ICMP- и IP-заголовков, семейство адресов и дополнительные заголовки. Один подобранный размер на одном направлении не описывает все пути и все моменты времени.',
    'SSH подключается, короткий ответ проходит, большой вывод зависает после добавления туннеля.',
    'Это согласуется с проблемой размера пакетов, но сначала сравнивают retransmission, сообщения Packet Too Big и размеры на границах туннеля. Увеличивать MTU наугад нельзя.',
    'Для IPv4 без опций при MTU 1500 вычисли максимальные данные ICMP echo с заголовками IP 20 и ICMP 8 байт. Затем учти туннельные 60 байт.',
    'Числа заголовков заданы для этого расчёта; реальные опции и инкапсуляция меняют результат. Измерения выполняй внутри учебного пути.')

add('ipv6', 'Соседство и маршруты без ARP',
    'IPv6 использует 128-битные адреса. Link-local адрес действует на локальном канале и часто требует указания интерфейса. Neighbor Discovery поверх ICMPv6 выполняет обнаружение соседей; ARP относится к IPv4. Router Advertisement может сообщать префикс и маршрут по умолчанию, SLAAC формирует адрес; DHCPv6 решает другие задачи конфигурации и не заменяет RA для обычного обнаружения default router.',
    'Несколько адресов на интерфейсе нормальны. Выбор исходного адреса и маршрута влияет на фактический путь. ICMPv6 нужен не только для ping, но и для соседства и сообщений Packet Too Big. Фильтр «запретить весь ICMP» ломает важные механизмы. DNS AAAA и работоспособный IPv6-маршрут проверяются независимо от A и IPv4.',
    'У гостя есть link-local адрес, но нет default route и глобальной связности.',
    'Наличие адреса не доказывает получение RA и маршрута. Сначала проверь область адреса, интерфейс и сообщения соседства.',
    'Сравни проверку соседа по link-local и сервера по глобальному адресу. Какой результат отделяет отсутствие маршрута от ошибки DNS AAAA?',
    'Не отправляй учебные RA в общую сеть. Изолированное пространство имён или отдельный мост предотвращает изменение маршрутов чужих машин.')

add('segments', 'Граница Ethernet и граница политики',
    'VLAN разделяет широковещательные домены Ethernet. Тег 802.1Q передаёт номер VLAN на конкретной линии; нетегированный кадр получает VLAN по настройке порта. PVID определяет классификацию такого входящего кадра, trunk переносит разрешённые VLAN. Изоляцию создаёт настройка коммутатора или моста, а не сам факт наличия числа в кадре. Linux bridge учит MAC и пересылает кадры; маршрутизатор пересылает IP между сетями.',
    'Network namespace имеет собственные интерфейсы, маршруты и сокеты. Veth соединяет два конца виртуальной линии. Bond объединяет интерфейсы по выбранному режиму; LACP согласует агрегирование со switch, но один поток обычно ограничен выбранным хешем одним участником. NAT меняет адреса/порты и не заменяет разрешающую политику; forwarding должен быть включён отдельно. Виртуальный мост и физический trunk нужно сопоставить по всему пути.',
    'ВМ отправляет нетегированный трафик, порт моста назначает VLAN 20, uplink разрешает только VLAN 10.',
    'Кадр классифицирован в VLAN, который не проходит uplink. Связь с самим хостом может при этом работать и не подтверждает путь до шлюза.',
    'Нарисуй теги на каждом участке от ВМ до физического порта. Затем предложи проверку запрета связи между двумя сегментами.',
    'Смена VLAN управления может оборвать доступ. Учебные изменения выполняй на отдельных мостах; один bond не доказывает независимость питания и коммутаторов.')

add('firewall', 'Правило применяется в конкретной точке пути',
    'Netfilter различает трафик к самому узлу, транзит и исходящие пакеты. Поэтому разрешение INPUT не открывает FORWARD. nftables организует таблицы, цепочки, точки подключения и правила. Порядок, приоритет цепочки и базовая политика влияют на результат; видимое правило в одном месте не описывает весь ruleset.',
    'Conntrack учитывает состояние потоков. Разрешение established/related не равно разрешению любого нового входящего соединения. DNAT может изменить адрес назначения до дальнейшего решения маршрутизации, SNAT — источник на выходе. Счётчик правила показывает совпавшие пакеты, а не успешный ответ приложения. Проверять нужно нужное семейство адресов, namespace и направление.',
    'Сервис доступен на хосте, но пакет от клиента гостевой сети проходит маршрутизацию и отбрасывается политикой FORWARD.',
    'Изменение INPUT не устранит этот отказ. Сопоставь фактический путь и счётчики; минимальное правило должно разрешать только нужный источник, назначение и порт.',
    'Запиши таблицу ожидаемых разрешений и запретов для двух клиентов. После исправления проверь оба исхода, включая новое соединение.',
    'Не очищай общий ruleset. Работай в выделенном namespace, сохраняй исходную политику и имей независимый доступ до эксперимента.')

add('disk-identity', 'От носителя до имени в Linux',
    'Носитель, контроллер, канал и блочное устройство — разные объекты. SATA обычно соединяет один накопитель с портом; SAS использует SCSI-модель команд и может включать expander, двухпортовые диски и несколько путей. HBA предоставляет устройства ОС, RAID-контроллер может вместо физических дисков предъявлять логические тома. Backplane связывает слоты с линиями и питанием; номер слота не выводится из буквы sdX.',
    'Обнаружение проходит через транспорт, драйвер, блочный слой и создание имён udev. /sys показывает связи с устройством и драйвером; /dev/disk/by-id помогает сопоставить постоянные идентификаторы. Серийный номер, WWN и UUID файловой системы обозначают разные уровни. ВМ может видеть виртуальный серийный номер и не иметь доступа к физическому SMART. Успешная запись через виртуальный диск зависит от обещаний гостя, гипервизора, контроллера и носителя.',
    'После перезагрузки /dev/sdb стал /dev/sdc, но WWN совпал, а UUID прежней файловой системы найден на нём.',
    'Изменилась перечислительная буква, а не обязательно накопитель. Для решения о замене дополнительно сопоставляют слот, контроллер и независимые идентификаторы.',
    'Построй цепочку «файл заметки → mount → том → устройство → путь → слот». Покажи, какие уровни скрывает RAID-контроллер.',
    'Не извлекай и не форматируй диск по одному имени /dev/sdX. Потеря целой полки прежде всего требует проверки общих питания и пути, а не одновременной замены всех дисков.')

add('disk-health', 'Состояние устройства и состояние пути',
    'NVMe предоставляет контроллер и namespaces — адресуемые пространства блоков. Namespace не обязательно является отдельным физическим носителем или доменом отказа. Очереди команд и интерфейс PCIe отличаются от SATA/SAS, поэтому одинаковая буква «диск» скрывает разные пути. RAID-контроллер может скрывать физические показатели и требовать своего интерфейса управления.',
    'SMART и NVMe health log содержат разные счётчики, пороги, температуры и ошибки. Оценка должна учитывать производителя, модель, время и прирост. Один общий PASS не доказывает отсутствие отказов. Ошибки носителя, тайм-ауты транспорта, resets контроллера и ошибки PCIe требуют разных проверок. Сравнивай журнал ядра, контроллер и собственные показатели накопителя.',
    'У нескольких дисков одновременно появились тайм-ауты, медиасчётчики не выросли, контроллер сообщил reset.',
    'Наблюдения указывают на общий путь как гипотезу. Отсутствие роста одного счётчика не оправдывает диск окончательно, но массовая замена без проверки контроллера не обоснована.',
    'Составь инвентарь controller/namespace/WWN/model/slot и сравни два снимка счётчиков во времени. Какие сведения недоступны из гостя?',
    'Чтение журналов отличается от запуска self-test, обновления прошивки и secure erase. Ресурсные и разрушительные операции не входят в первичную проверку здоровья.')

add('filesystem', 'У каждого слоя свой размер и свои метаданные',
    'GPT описывает разделы устройства; файловая система хранит имена, inode, размещение и свободные блоки. Между ними могут находиться md RAID и LVM. Метаданные каждого слоя описывают только свой уровень: увеличение LV не меняет автоматически размер файловой системы. Журнал ext4 защищает согласованность журналируемых структур; в обычном data=ordered содержимое всех файлов не журналируется целиком. XFS также имеет собственную модель журнала и процедуры изменения размера.',
    'При росте сначала обеспечивают больший нижний слой, затем расширяют верхний подходящим инструментом. При уменьшении верхний должен заранее помещаться в меньший нижний; поддержка зависит от файловой системы и версии, универсальной обратной команды нет. Удалённый, но открытый файл продолжает занимать место до закрытия последних ссылок ядра. TRIM/discard сообщает нижнему устройству о свободных блоках и не заменяет проверку содержимого. Удаление LV не стирает сразу все блоки, но восстановление метаданных не гарантирует данные после новых записей.',
    'LV показывает 200 GiB, а df — 100 GiB.',
    'Результаты относятся к разным слоям. Сначала устанавливают тип ФС и источник mount; только затем выбирают поддерживаемое расширение.',
    'Нарисуй расположение метаданных GPT, PV/VG/LV и ext4. Объясни, почему журнал, RAID и резервная копия защищают от разных событий.',
    'mkfs создаёт новую ФС и уничтожает прежнюю структуру. Для опыта используется только созданный проверяющим кодом образ; рабочие устройства не подходят.')

add('lvm', 'Логическое место и физическая ёмкость',
    'PV — физический том, VG объединяет доступные extents, LV получает отображение на них. Свободное место внутри файловой системы и свободные extents VG — разные запасы. Расширение LV возможно при достаточном нижнем ресурсе, но чтение прежней границы через df указывает, что верхняя ФС ещё не выросла.',
    'Thin provisioning выдаёт логическую ёмкость по мере записи. Обещанные размеры могут превышать физический thin pool; исчерпание данных или метаданных требует отдельного наблюдения. Snapshot сохраняет представление состояния и потребляет ресурс при изменениях. Замена PV — процедура с проверкой идентичности, переноса extents, завершения перемещения и последующей проверки; нельзя отсоединять устройство только потому, что команда начала работу.',
    'В thin pool занято 92% данных, а внутри одного гостя df показывает лишь 30%.',
    'Гость не видит расход всего пула и других томов. Его свободные блоки не обещают свободного физического места для будущей записи.',
    'Составь три независимых условия безопасного роста: нижняя ёмкость, размер LV, размер и целостность ФС. Что добавится для thin pool?',
    'Уменьшение и удаление томов не используются как обычный откат учебного роста. В лаборатории возвращают отдельный образ; production-процедура требует копии и версии инструментов.')

add('mirror', 'Какие отказы переживает массив',
    'RAID0 распределяет данные без резерва; RAID1 хранит копии, RAID5 использует одну контрольную часть, RAID6 — две. RAID10 объединяет зеркала с распределением; допустимость двух отказов зависит от того, какие пары потеряны. Ёмкость, скорость и отказоустойчивость зависят от схемы, размера блока и нагрузки. HBA и аппаратный RAID меняют, какой слой отвечает за сборку и кэш.',
    'Degraded означает потерю части избыточности, не обязательно потерю данных. Rebuild читает оставшиеся данные и восстанавливает резерв, создавая нагрузку и окно риска. Проверяют роли участников и UUID массива, а не только изменчивое имя /dev/mdX. Нельзя добавлять неизвестный диск как «правильный» по его размеру. Расширение массива или LV не означает расширение находящейся выше файловой системы.',
    'В RAID10 отказали два диска. В первом варианте это разные половины разных зеркал, во втором — оба диска одного зеркала.',
    'Число отказов одинаково, последствия различны. Нужна реальная раскладка данных и пар; слово RAID10 не доказывает переносимость любой двойной потери.',
    'Для четырёх дисков по 1 TB рассчитай номинальную полезную ёмкость RAID1 всех четырёх, RAID5 и RAID10. Перечисли общие контроллер, питание и ошибки оператора.',
    'Массив не заменяет копию. Ошибочное удаление и шифрование могут распространиться на все копии; проверка rebuild не является испытанием восстановления независимого архива.')

add('storage-path', 'Где меняется граница ответственности',
    'Аппаратный RAID предъявляет ОС виртуальный том, а физические диски, rebuild и cache policy управляются контроллером. В HBA-режиме ОС получает более прямое представление дисков, но по-прежнему зависит от транспорта и прошивки. Write-back подтверждает запись до её попадания на основной носитель и требует подходящей защиты кэша; write-through имеет иной момент подтверждения.',
    'SAS expander соединяет несколько устройств с uplink; SAS address идентифицирует порт или устройство соответствующего уровня. SES предоставляет сведения об enclosure и слотах, но маркировку нужно сверять с реальной полкой. Двухпортовый SAS допускает разные пути, если вся топология их поддерживает. Два кабеля к одному контроллеру не убирают его общий отказ. Состояния online, failed, foreign, hot spare трактуются по конкретному контроллеру.',
    'Все диски одной полки исчезли одновременно, диски другой полки того же массива видны.',
    'Сначала исследуй общий участок: питание полки, uplink, expander и журнал контроллера. Совпадение по времени сильнее поддерживает общий путь, чем независимые отказы всех носителей.',
    'Нарисуй два пути от ОС к одному SAS-диску. Закрась общие участки и назови, какой отказ останется непереносимым.',
    'Импорт foreign configuration, очистка метаданных и смена режима HBA/RAID меняют интерпретацию данных. Их нельзя использовать как пробную диагностику.')

add('write-cache', 'Кто пообещал сохранить байты',
    'Приложение передаёт данные ядру, затем они могут пройти page cache, кэш гипервизора, контроллера и накопителя. Успешный write обычно означает принятие байтов, а не прохождение всей цепочки до энергонезависимого носителя. fsync просит соответствующую гарантию файловой системы; flush и FUA передают требования ниже. Реальная гарантия зависит от честного исполнения всеми слоями.',
    'Защищённый write-back может быть корректным и быстрым, если кэш и восстановление действительно переживают предусмотренный отказ. Исчерпанная батарея или неисправная защита могут переключить политику в write-through и повысить задержку. Нельзя возвращать скорость отключением барьеров без изменения требований к долговечности.',
    'После предупреждения защиты кэша задержка синхронных записей выросла, чтение почти не изменилось.',
    'Проверь фактическую cache policy и состояние защиты. Замедление согласуется с изменением момента подтверждения, а не обязательно с деградацией носителя.',
    'Расположи подтверждения write, fsync и контроллера на одной схеме. Какие измерения нужны, чтобы сравнить две политики при одинаковой гарантии?',
    'Испытание потери питания — отдельная аппаратная процедура на расходуемых данных. Быстрый fio и чистый shutdown не доказывают устойчивость к внезапному обесточиванию.')

add('network-storage', 'Блоки и файлы требуют разного владельца',
    'iSCSI предоставляет инициатору блочный LUN от target через IP. IQN задаёт идентичность участника; сеть, сессия, аутентификация и разрешение на LUN проверяются отдельно. Две машины, получившие один блочный ресурс, не могут безопасно одновременно монтировать обычную ext4 для записи без специальной координации. NFS и SMB предоставляют файловый интерфейс с серверной стороной управления.',
    'Для NFS важны версия протокола, exports, сопоставление UID/GID, права и политика root mapping. Доступный порт не доказывает разрешение на конкретный файл. Для SMB дополнительно важны учётные данные, share и права файловой системы. ZFS организует локальные пулы и наборы данных; Ceph распределяет объекты между узлами. Это разные границы абстракции, не взаимозаменяемые названия сетевого диска.',
    'NFS mount выполнен, но пользователь не может читать заметку; тот же UID на сервере не совпадает с владельцем файла.',
    'Связность и mount уже проверены. Следующая граница — идентичность и доступ к объекту, а не повторная настройка маршрута.',
    'Сравни собственников файловой системы для iSCSI, NFS и SMB. Что нужно согласовать, прежде чем два клиента начнут запись?',
    'Локальный экспорт внутри одной ВМ проверяет протокол и права, но не независимый отказ удалённого сервера. Не публикуй учебный export на общей сети.')

add('multipath', 'Несколько путей к одному объекту',
    'Multipath объединяет пути к одному блочному устройству по устойчивой идентичности, обычно WWID. Совпавшая ёмкость недостаточна: два разных LUN такого же размера нельзя объединять. Приложение должно использовать созданное составное устройство, а не случайный /dev/sdX. Политика выбора пути, проверка живости и ALUA влияют на активные пути и время переключения.',
    'Отказ пути и отказ хранилища различаются. Если все пути ведут к одному контроллеру или проходят через один switch, этот общий компонент остаётся доменом отказа. Очередь при потере всех путей может задерживать I/O; её поведение задаётся конкретной политикой и версиями. Оценивать нужно также время отказа и восстановления, а не только наличие двух строк.',
    'Один LUN обнаружен четырежды с одинаковым WWID. Данные создают через один из отдельных путей.',
    'Обнаружение нескольких представлений не означает четыре независимых диска. Нужны корректное составное устройство и проверка, что workload использует именно его.',
    'Нарисуй исходный и оставшийся путь после отказа. Какие журналы и измерения подтверждают, что запись продолжилась без смены логического объекта?',
    'Учебный DM failover по двум loop-путям показывает механизм блочного слоя. Он не доказывает независимость HBA, сети, контроллеров и питания.')

add('zfs', 'Снимок хранит старые блоки, а не независимый сервер',
    'ZFS объединяет управление пулами и файловыми системами. Vdev определяет группу хранения, из которой строится pool; надёжность пула зависит от устройства каждого vdev. Copy-on-write записывает новые версии блоков, сохраняя старые для снимков. Контрольные суммы позволяют обнаружить несоответствие данных; исправление требует доступной корректной копии или избыточности.',
    'Snapshot сначала разделяет блоки с текущими данными, но удерживает старые блоки при изменении и удалении файлов. Поэтому бесплатный при создании снимок может позднее занимать значительное место. Scrub проверяет читаемые данные и, при достаточной избыточности, исправляет обнаруженные ошибки; он не отменяет логически ошибочную запись пользователя. Send/receive может перенести снимки на другой ресурс, чья независимость требует отдельной проверки.',
    'Удалён большой файл, но свободного места почти не прибавилось. Его старая версия есть в snapshot.',
    'Блоки всё ещё нужны снимку. Удаление имени из текущего dataset не освобождает блоки, на которые есть другие ссылки.',
    'Сравни расход сразу после snapshot и после перезаписи половины файла. Как восстановить одну заметку, не откатывая весь набор данных?',
    'Rollback меняет текущее состояние и может уничтожить более новые изменения. Для учебного опыта используй отдельный pool на созданных образах; локальный snapshot не является независимой резервной копией.')

add('ceph', 'Избыточность зависит от размещения',
    'Ceph RADOS хранит объекты на OSD. Клиент получает карту кластера и определяет размещение через CRUSH; placement group группирует объекты для управления размещением. MON поддерживают карты и кворум управления; число MON не равно числу копий данных. RBD предоставляет блочный интерфейс, CephFS — файловый с дополнительными метаданными.',
    'В replicated pool size задаёт желаемое число копий, min_size — нижний порог для разрешения I/O, а не полное описание протокола подтверждения долговечности. CRUSH failure domain определяет разнесение по host/rack и другим уровням. Три OSD одного физического сервера не переживают потерю этого сервера как три независимых узла. Recovery/backfill требуют сети, места и времени; HEALTH_OK не описывает пригодность всех пользовательских путей.',
    'size=3, все копии размещены на дисках одного хоста. Хост обесточен.',
    'Количество копий не обеспечило доступность при этом отказе. Нужна политика разнесения по независимым хостам и проверка её фактического выполнения.',
    'Для трёх физических узлов укажи desired replicas, минимальный запас места и ожидаемую деградацию при отказе одного узла. Какие предположения о сети и питании остаются?',
    'Снижение min_size ради зелёной панели меняет риск. Ceph не нужен для первой страницы с заметкой; выбирать его следует по требованиям и способности обслуживать распределённую систему.')

add('benchmark', 'Измеряется нагрузка на систему',
    'IOPS считает операции, bandwidth — байты в секунду, latency — время операции. При фиксированном размере блока 4 KiB поток 10000 IOPS соответствует примерно 39,1 MiB/s полезных данных. Случайный доступ отличается от последовательного, чтение от записи, синхронное подтверждение от буферизованной передачи. Глубина очереди определяет число незавершённых операций; высокая полоса при большой очереди может сопровождаться неприемлемым ожиданием.',
    'Размер набора данных и режим I/O определяют, измеряется ли память, кэш или нижний путь. iostat агрегирует счётчики устройств, iowait относится к учёту времени CPU и не называет виновный диск. perf исследует выполнение CPU, ftrace — события ядра, eBPF — программируемые точки наблюдения с ограничениями ядра и прав. Каждый инструмент имеет накладные расходы и свою точку измерения.',
    'После первого прохода чтение ускорилось в десять раз, рабочий набор помещается в RAM.',
    'Сравнение согласуется с прогретым кэшем. Нельзя объявить физический диск в десять раз быстрее без опыта, различающего кэш и носитель.',
    'Составь матрицу из шести опытов с фиксированным объёмом, размером блока, очередью и способом подтверждения. Укажи, какие параметры менять по одному.',
    'Записывающий benchmark может уничтожить данные и заполнить пул. Используй только отдельный файл или образ, заданный лабораторией; не подставляй системный /dev-узел.')

add('latency', 'Среднее скрывает хвост',
    'Задержка имеет границы измерения: ожидание до отправки, выполнение в системе, получение подтверждения. Среднее — сумма интервалов, делённая на число наблюдений. Перцентиль описывает выбранную позицию распределения, но его значение зависит от метода расчёта и достаточного объёма выборки. Для десяти запросов точная оценка p99 неубедительна.',
    'В устойчивой системе закон Литтла связывает среднее число задач L, интенсивность λ и среднее время W: L=λW при одинаковой границе наблюдения. Увеличение очереди может повысить throughput до насыщения и затем лишь увеличить ожидание. Completion latency benchmark не обязательно включает всю очередь приложения или синхронную запись базы.',
    '99 ответов занимают 10 ms, один — 1010 ms.',
    'Среднее равно 20 ms, но один пользователь ждал больше секунды. Среднее не описывает этот случай; нужны распределение и условия медленного ответа.',
    'При 200 запросах/s и среднем времени 0,05 s вычисли L. Как изменится вывод, если число запросов в очереди постоянно растёт?',
    'Для интервалов используй монотонные часы. Сопоставляй одинаковые окна нагрузки; не выводи причинность из одного совместного пика графиков.')

add('database-write', 'Транзакция и путь подтверждения',
    'WAL — журнал опережающей записи: сведения, необходимые для восстановления изменения, записываются прежде соответствующих изменённых страниц данных. COMMIT получает смысл из настройки долговечности СУБД и гарантий нижнего хранения. Успешный системный write не заменяет требуемый flush; слой, который преждевременно подтверждает сохранность, разрывает цепочку.',
    'База часто сочетает небольшие синхронные записи журнала, случайные обращения к страницам и фоновые checkpoint. Репликация бывает синхронной и асинхронной с разными условиями подтверждения. Отстающая реплика не гарантирует все последние транзакции. PITR восстанавливает базовую копию и последовательность журналов до выбранного момента; отсутствие участка WAL ограничивает восстановление. Согласованная копия требует процедуры конкретной СУБД, а не только копирования открытых файлов.',
    'Клиент получил COMMIT, а после аварии последние записи отсутствуют; включён асинхронный режим подтверждения.',
    'Сначала сопоставь заявленную гарантию с настройкой. Это может быть ожидаемым риском режима; обвинять носитель без проверки цепочки нельзя.',
    'Нарисуй места записи WAL, страниц, replica acknowledgement и ответа клиенту. Что потребуется для восстановления на минуту до ошибочного DELETE?',
    'Power-loss испытание проводится отдельно на расходуемых данных. Перезапуск программы не моделирует потерю питания кэша контроллера и накопителя.')

add('restore-point', 'Цель потери данных и фактическая точка',
    'RPO задаёт допустимую потерю данных в единицах времени, RTO — допустимое время восстановления услуги. Это цели, а не автоматически достигнутые свойства расписания. Возраст доступной корректной точки и время реального восстановления измеряются отдельно. Snapshot зависит от исходного ресурса; независимая копия должна переживать выбранный домен отказа.',
    'Для восстановления нужны данные, конфигурация, ключи, права, совместимая программа и последовательность действий. PITR добавляет журналы между базовой копией и нужным моментом. Успешное создание архива не доказывает читаемость и пригодность. Проверяют восстановление в отдельном месте и реальный пользовательский результат; желательно также наличие ожидаемых и отсутствие нежелательных записей.',
    'RPO — 15 min, последняя проверенная копия старше аварии на 60 min, журналы за этот час недоступны.',
    'Цель не выполнена. Наличие расписания каждые 15 min не меняет фактически восстанавливаемую точку.',
    'Составь приёмку восстановленной заметки: версия данных, права, ответ программы, затраченное время. Как изменится план при утрате ключа шифрования?',
    'Не перезаписывай единственный источник при первой попытке восстановления. Отдельный адрес, изоляция отправки и сохранённый исходный архив позволяют проверить результат без двойной записи.')

add('shell-data', 'Байты, слова и структурированные записи',
    'Bash связывает программы потоками байтов. Кавычки сохраняют один аргумент там, где незакавыченное раскрытие может разделить слова и раскрыть шаблоны имён. Массив хранит отдельные аргументы; строки имён файлов нельзя надёжно получать через разбор ls. grep выбирает строки по шаблону, awk разбирает записи и поля, sed преобразует текст. jq работает со структурой JSON: поле с именем надёжнее позиции в человеческой таблице.',
    'Код возврата — отдельный канал результата. grep с кодом 1 может означать отсутствие совпадений, а не отказ чтения. set -e зависит от контекста команды; он не заменяет явную обработку ожидаемых отказов. pipefail позволяет увидеть отказ в конвейере, который иначе мог бы завершиться кодом последней успешной программы. stderr нельзя смешивать с JSON в stdout, если его затем разбирает другая программа.',
    'В таблице рядом стоят CPU temperature и inlet temperature. grep temperature возвращает обе строки; скрипт берёт первую.',
    'Условия выбора недостаточны: порядок вывода не определяет нужный датчик. Выбирай устойчивый идентификатор и проверяй единицу и количество найденных записей.',
    'Предскажи аргументы для пути с пробелом и для шаблона *.log. Как обработать ноль, одну и две записи нужного датчика без молчаливого выбора?',
    'Сборщик сначала только читает. Не вставляй данные в eval и командную строку; кавычки не превращают недоверенный код в безопасный.')

add('shell-failure', 'Ошибка должна иметь наблюдаемый исход',
    'Диагностическая команда может завершиться успешно, отказать, превысить время или выдать неполные данные. Эти состояния нужно хранить отдельно. Тайм-аут ограничивает ожидание, но не доказывает отсутствие побочного действия. Повтор допустим только с пониманием, была ли операция идемпотентной и могла ли первая попытка уже выполниться.',
    'Для каждой внешней команды сохраняют код, stderr, длительность и проверку формата stdout. В GNU timeout код 124 обычно обозначает срабатывание ограничения при стандартном режиме; другие опции и отказ самого timeout меняют трактовку. Нельзя заменять любой отказ пустой строкой или нулевой температурой: это превратит неизвестное в норму.',
    'Датчик не ответил за 2 s, скрипт записал temperature=0 и status=ok.',
    'Отсутствие наблюдения ошибочно стало измерением нуля. В отчёте нужны timeout и отсутствие значения; потребитель не должен принимать его как здоровый датчик.',
    'Опиши результат для успеха, кода 7, пустого JSON и тайм-аута. Затем проверь, что скрипт действительно заканчивает зависшую команду.',
    'Не повторяй автоматически запись конфигурации после неизвестного исхода. Сначала проверь текущее состояние и ограничь число попыток.')

add('python-result', 'Результат инструмента — структура',
    'subprocess.run с массивом аргументов передаёт их без интерпретации shell. capture_output собирает stdout и stderr отдельно; returncode обозначает исход процесса. check=True превращает ненулевой код в исключение, timeout ограничивает ожидание. JSON-парсер проверяет синтаксис, а схема и типы — смысл полей. Человеческий вывод может меняться после обновления или смены языка.',
    'argparse задаёт интерфейс команды, logging направляет диагностические сообщения отдельно от машинного результата. Обрабатывай ожидаемые исключения на границе инструмента и сохраняй причину: unavailable, timeout, invalid-data или failed. HTTP имеет транспортный исход и статус ответа; успешный HTTP ещё требует проверки тела. Секреты не должны попадать в argv, отчёт и traceback. Конкурентный опрос сокращает суммарное ожидание независимых узлов, но требует лимита параллельности и отдельного результата каждого.',
    'Команда завершилась кодом 2, stdout пуст, stderr содержит причину отказа. Старый скрипт пытается разобрать stdout как успешный JSON.',
    'Первичная ошибка — отказ процесса; ошибка JSON вторична. Сначала классифицируй исход, затем разбирай ожидаемый формат.',
    'Спроектируй JSON-результат с версией схемы, целью, временем, кодом, статусом и наблюдениями. Проверь его на успехе и двух разных отказах.',
    'Не запускай ученический код от root. Повторные попытки HTTP ограничивай временем и применяй только с учётом идемпотентности операции.')

add('api-pages', 'Один ответ не обязательно весь инвентарь',
    'REST API предоставляет ресурсы через адреса и методы. GET обычно читает, но контракт конкретного API нужно проверить. JSON — формат представления, не гарантия полноты. Коллекция может возвращаться страницами с next link, cursor или номером страницы. Следующий адрес и окончание обхода определяются контрактом, а не догадкой о числе элементов.',
    'При обходе сохраняют идентичность каждого объекта, обнаруживают повтор cursor и дубликаты. На меняющемся наборе данных разные страницы могут относиться к разным моментам; при наличии snapshot token используют его. Rate limit и Retry-After требуют ограниченных пауз. Аутентификация и доступ к отдельному ресурсу проверяются независимо от права прочитать коллекцию.',
    'Первая страница содержит 100 серверов и next; скрипт сообщает «всего 100» и завершается.',
    'Скрипт измерил размер страницы, а не всего инвентаря. Сначала нужно пройти продолжение и явно отметить, завершён ли обход.',
    'Придумай три ответа: две страницы, повторяющийся cursor и отказ на второй странице. Каким будет статус полноты отчёта в каждом случае?',
    'Не отправляй токен по произвольному next URL другого origin. Политика переходов, TLS и разрешённые адреса — часть клиента, а не свойство JSON.')

add('git-change', 'Версия желаемого состояния',
    'Git commit фиксирует снимок подготовленных в index файлов и метаданные. Неотслеживаемые и не добавленные изменения не появляются в нём автоматически. Diff рабочего дерева, index и последнего commit отвечают на разные вопросы. Секрет, попавший в историю, требует отзыва и отдельного удаления из истории: новый commit с удалённым файлом не стирает старые версии.',
    'Ansible описывает состояние через inventory, переменные, facts, modules, templates и roles. Группы inventory выражают роли узлов, а не только адреса. Handler запускается при уведомлении об изменении. Идемпотентность означает повторное достижение того же состояния без лишних изменений, но зависит от модуля и описания задачи. Git хранит намерение и процедуру, а наблюдение реального узла выявляет drift — отклонение от этого намерения.',
    'После первого применения changed=3, после второго changed=0. Затем администратор вручную поменял конфигурацию на сервере.',
    'Второй прогон подтвердил устойчивость того состояния, но не вечное отсутствие drift. Следующее сравнение должно обнаружить отклонение и показать конкретный diff.',
    'Раздели в репозитории шаблон, inventory, пример переменных и зашифрованные/внешние секреты. Как доказать, что работающий сервер соответствует конкретному commit?',
    'Хеш commit идентифицирует источник, но сам по себе не доказывает его применение. Проверяй фактическое состояние и не сохраняй пароли в открытых примерах.')

add('ansible-state', 'Проверочный прогон имеет границы',
    'Ansible check mode моделирует изменения только там, где модуль и задача это поддерживают. Это не песочница. Задача с check_mode: false может реально выполниться даже в проверочном прогоне; shell и внешние системы требуют особого внимания. --limit ограничивает выбранные хосты, но нужно также проверить inventory, delegation и область побочных действий.',
    'Diff полезен для конфигурации, но может раскрыть секреты. Handler срабатывает после уведомления; порядок и условия влияют на фактический restart. Безопасная лестница — один учебный узел, проверка результата, повтор без изменений, обнаружение намеренного drift, затем расширение области.',
    'Playbook в check mode показывает changed=0 для неподдерживаемого шага, а shell-задача явно исключена из check mode.',
    'Нельзя заключить, что прогон ничего не менял или полностью проверил изменение. Нужны контракты каждой задачи и наблюдение целевого узла.',
    'Укажи, что должно измениться в первом прогоне и остаться прежним во втором. Внеси контролируемое отклонение только в созданном учебном файле.',
    'Перед запуском проверь цель, пользователя, привилегии и точный набор задач. Не применяй учебный inventory к рабочей инфраструктуре.')

add('vm-resources', 'У виртуального ресурса есть физическая цена',
    'KVM предоставляет ядру Linux механизм аппаратной виртуализации, QEMU моделирует машину и устройства, libvirt управляет ими через общий интерфейс. Proxmox добавляет собственное управление ВМ и хранением. ВМ представлена процессами хоста; vCPU планируются на логические CPU и могут ждать. Модель CPU host раскрывает возможности текущего хоста, но ограничивает переносимость на другой процессор.',
    'Память, настроенная для ВМ, память, реально выделенная хостом, и доступная память внутри гостя — разные величины; ballooning и overcommit требуют запаса и наблюдения. Virtio уменьшает издержки эмуляции. Raw и qcow2 различаются размещением и возможностями, но гарантия записи зависит также от cache mode и нижнего хранения. Cloud-init формирует экземпляр; мост и VLAN задают сетевой путь, который гость не видит целиком.',
    'Гостю назначены 4 vCPU, на перегруженном хосте выполнение замедлилось без изменения кода.',
    'Назначение четырёх vCPU не резервирует четыре физических ядра. Сравни нагрузку хоста, ожидание планирования и фактическую производительность гостя.',
    'Сопоставь схему виртуального диска с реальным хранилищем и мост ВМ с физическим uplink. Какие обещания гостя зависят от настроек хоста?',
    'Видимая гостю топология не доказывает топологию физического сервера. Изменение ресурсов, cache mode и сетей требует отдельного опыта и пути возврата.')

add('vm-backup', 'Восстановленная ВМ — новый проверяемый объект',
    'Снимок хранит точку состояния в рамках поддерживающего её хранилища; резервная копия переносит данные в архив. Копия дисков работающей ВМ может требовать quiesce и участия приложения. QEMU guest agent помогает управлять гостем, но его наличие не делает автоматически согласованной любую базу.',
    'Проверка копии — запуск отдельного восстановленного экземпляра, проверка данных и ответа, затем безопасная очистка. Изолируй сеть, чтобы восстановленная ВМ не получила идентичность и роль активного источника. Исходная ВМ и архив сохраняются до подтверждения результата. VMID — идентификатор объекта Proxmox, а не содержимого архива.',
    'Архив создан успешно; восстановленная ВМ загрузилась, но приложение читает другой пустой каталог.',
    'Код завершения архива и загрузка ОС недостаточны. Нужно получить контрольную заметку через тот же прикладной путь, ради которого создавалась копия.',
    'Опиши подготовку, backup, restore в новый VMID, проверку HTTP-ответа и повтор. Где сохраняются commit, состояние ВМ и контрольное содержимое?',
    'Учебный исполнитель клонирует источник и удаляет только принадлежащие попытке объекты. Его native Proxmox-цикл пока требует живой приёмки; чтение этого разбора не засчитывает восстановление.')

add('container', 'Один kernel, разные представления',
    'Контейнер — процессы общего ядра с выбранными namespaces и ограничениями cgroups. Namespace меняет видимость PID, сети, mount и других ресурсов; cgroup учитывает и ограничивает использование. Это не отдельное ядро, как у ВМ. Образ содержит слои файлов и настройки, контейнер добавляет изменяемый слой и состояние процесса. Overlayfs объединяет нижние слои и верхние изменения; удаление может представляться специальной отметкой, не стирая нижний слой.',
    'Dockerfile описывает сборку, build context определяет доступные файлы: случайно включённый секрет может остаться в слое. Volume и bind mount выносят данные за жизненный цикл контейнера и сохраняют обычные вопросы UID и прав. Cgroup v2 задаёт лимиты CPU/памяти; OOM в группе не обязательно означает исчерпание RAM хоста. root в контейнере и privileged режим имеют разные риски; доступ к Docker socket даёт широкую власть над хостом.',
    'После удаления контейнера заметка из его writable layer исчезла, а файл bind mount сохранился.',
    'У данных были разные владельцы жизненного цикла. Перезапуск, пересоздание контейнера и восстановление volume — разные действия.',
    'Нарисуй образ, изменяемый слой, volume, процесс и общий kernel. Какие части нужны для повторного развёртывания без потери заметки?',
    'Не используй privileged и host mounts как универсальное исправление прав. Учебные образы загружают заранее и фиксируют по содержимому; тег сам по себе изменяем.')

add('container-network', 'От имени Compose до слушателя',
    'Сеть контейнера часто включает veth и bridge. Публикация host-port связывает внешний адрес с портом контейнера, но процесс внутри должен слушать подходящий адрес, а не только loopback. В Compose имена служб разрешаются в соответствующей сети; адрес контейнера может смениться после пересоздания. depends_on задаёт зависимость запуска; ожидание готовности требует healthcheck и предусмотренного условия либо повторов в приложении.',
    'Показания free и nproc зависят от интерфейсов и версий и могут не совпадать с лимитами cgroup. Проверять лимиты нужно в действительной конфигурации, а не считать видимые CPU гарантированными. Локальная публикация на 127.0.0.1 и публикация на всех адресах имеют разную доступность. Поведение сетевой изоляции зависит от версии Docker; учебная среда требует актуальных исправлений.',
    'Из соседнего контейнера имя web разрешается, но соединение отклоняется. Внутри web программа слушает 127.0.0.1:8000.',
    'DNS сработал, но слушатель ограничен loopback своего namespace. Смена внешнего маршрута не исправит эту границу.',
    'Проследи запрос: имя → адрес контейнера → порт → слушатель → заметка. Затем проверь готовность после пересоздания зависимой службы.',
    'Не публикуй учебный сервис на всех интерфейсах ради удобства. Отдельно проверяй адрес bind и фактическую доступность с разрешённого и запрещённого источника.')

add('delivery', 'Артефакт проходит проверяемые переходы',
    'CI запускает проверки для определённого источника, CD переносит принятый артефакт в среду. Репозиторий кода, registry образов и работающий deployment — разные объекты. Артефакт фиксируют digest, а сборку связывают с commit и входами. Пример GitLab CI или другого движка выражает стадии и зависимости, но файл pipeline сам не доказывает успешный запуск.',
    'В Kubernetes Pod — единица запуска, Deployment поддерживает набор экземпляров, ConfigMap передаёт конфигурацию, Secret — выделенный тип для чувствительных данных без автоматической гарантии шифрования во всех местах. PV/PVC описывают хранение и его привязку, Ingress — правила входа при наличии контроллера. Helm рендерит и устанавливает набор ресурсов; rendered diff нужен до изменения. Reconciliation стремится к описанному состоянию, но не исправляет ошибочное намерение.',
    'Тесты прошли для digest A, а развёртывание скачало изменившийся тег, указывающий на B.',
    'Цепочка доказательств разорвана: проверялся другой артефакт. Стабильное имя тега не заменяет идентичность содержимого.',
    'Составь переходы «commit → build → test → registry digest → deploy → ответ → rollback». Какие свидетельства нужны на каждой границе?',
    'Автоматизация не даёт разрешения публиковать. Первое развёртывание проверяй на изолированной среде; миграция данных может сделать простой rollback образа недостаточным.')

add('terraform', 'План сравнивает три представления',
    'Terraform сопоставляет конфигурацию, сохранённое state и наблюдение provider. State связывает адрес ресурса в конфигурации с внешним объектом и может содержать чувствительные данные. Drift — изменение внешнего состояния относительно ожиданий. Plan — предложенные действия для конкретных входов; apply выполняет изменение, если среда и условия позволяют.',
    'Удалённый backend и locking помогают нескольким исполнителям координировать state, но блокировка не заменяет владение процессом изменения. Версии provider и зависимости фиксируют. Import связывает существующий объект с управлением, а удаление записи state и удаление реального ресурса — разные операции. Замена ресурса может означать его уничтожение и создание нового, даже если намерение звучит как «обновить параметр».',
    'В плане рядом с базой указан replacement, а инструкция автора обещает только смену имени.',
    'Оценивают действия плана, а не обещание. Нужно установить причину замены, влияние на данные, зависимости и способ возврата.',
    'Раздели изменения конфигурации, state и внешнего объекта. Как проверить drift без немедленного apply?',
    'Не применяй учебный план к реальному provider account. Секреты state защищаются отдельно; сохранённый plan также может содержать чувствительные значения.')

add('kubernetes', 'Контроллер, планировщик и приложение',
    'API хранит желаемые объекты, контроллеры сравнивают желаемое и фактическое состояние, scheduler выбирает узел, kubelet запускает контейнеры через runtime. Running означает стадию жизни Pod, Ready — допуск к обслуживанию по заданным условиям. Liveness может инициировать restart, readiness снимает готовность, startup probe даёт время запуска. Неправильно выбранная probe способна сама создавать отказ.',
    'Requests участвуют в планировании и распределении ресурсов, limits задают ограничения исполнения. Pending может означать невозможность разместить requests; CPU limit способен вызвать throttling, memory limit — OOMKilled. Сеть, хранилище и конфигурация остаются отдельными зависимостями. Reconciliation заменит потерянный экземпляр, но не восстановит отсутствующий секрет и не исправит неверный selector. Маленькой странице не нужен кластер без соответствующих требований.',
    'Pod Running, readiness падает; EndpointSlice содержит адрес с ready=false.',
    'Процесс существует, но не считается готовым endpoint. Сначала проверяй probe, порт, зависимости и фактический ответ, а не увеличивай число реплик.',
    'Различи четыре причины: Pending из-за requests, OOMKilled, Ready=false и selector без совпадений. Для каждой назови следующий наблюдаемый объект.',
    'Используй отдельный kind cluster и явный kubeconfig. Контекст рабочего кластера не должен быть неявной целью учебных команд.')

add('service-selector', 'Как Service выбирает получателей',
    'Service выбирает набор Pod по labels через selector. EndpointSlice описывает адреса, порты и условия endpoints; наличие строки с адресом не равнозначно ready=true. Service port и targetPort относятся к разным концам перенаправления; именованный targetPort должен соответствовать порту Pod. DNS-имя Service обычно приводит к сервисной точке, а не проверяет готовность приложения.',
    'Путь зависит от реализации dataplane, CNI и политики сети. Сначала отделяют отсутствие подходящих endpoints от ошибки доставки к готовому Pod. Прямое обращение к Pod полезно как диагностическое сравнение, но не является ремонтом Service. Изменение label может повлиять на несколько selectors и политики одновременно.',
    'Service ищет app=notes, а готовый Pod имеет app=note. Условия readiness успешны.',
    'Готовый процесс не выбран этим Service. Минимальное исправление должно согласовать намеренный selector и метку, сохранив область выбора.',
    'Запиши путь «Service → selector → EndpointSlice → targetPort → слушатель». Предскажи результат при правильной метке, но неверном targetPort.',
    'Не расширяй selector до всех Pod ради появления адресов. Проверяй отсутствие лишних получателей и реальный ответ через Service.')

add('cpu-numa', 'Расположение вычисления и памяти',
    'CPU выполняет инструкции, обращаясь к регистрам, кэшам и памяти. Поток аппаратного исполнения виден Linux как логический CPU; он не обязательно имеет независимые вычислительные блоки целого ядра. Сокет, package, die, core и thread описывают разные уровни, и современные платформы не обязаны связывать их один к одному. DMA позволяет устройству передавать данные без копирования каждого байта процессором, но требует корректных адресов и согласованности.',
    'NUMA объединяет CPU и память с разной стоимостью доступа. Локальная память обычно ближе, но результат зависит от нагрузки и контроллеров. Каналы памяти влияют на полосу и правила установки DIMM. Таблицы страниц переводят виртуальные адреса в физические, TLB кеширует переводы; большие страницы уменьшают число переводов ценой других компромиссов. THP — управляемый механизм больших страниц, а не универсальное ускорение. Overcommit, cgroup limits и OOM рассматриваются отдельно от номинальной установленной ёмкости.',
    'Потоки привязаны к CPU узла 0, а страницы расположены преимущественно на узле 1.',
    'Есть удалённый доступ, но сам факт не доказывает, что он — узкое место. Нужны одинаковая нагрузка и сравнение локального и удалённого размещения.',
    'Нарисуй путь «инструкция → TLB/таблицы → кэш → контроллер → DIMM». Какие сведения гостя нужно сопоставить с физическим хостом?',
    'Гостевые NUMA-узлы могут быть искусственными. Опыты с привязкой не подтверждают ECC и физическую исправность каналов памяти.')

add('ecc', 'Исправленная ошибка всё равно наблюдение',
    'ECC использует избыточность для обнаружения и исправления определённых ошибок в пределах выбранного кода и реализации. Она не означает защиты от любого сочетания ошибок или любой неисправности адресации. Corrected и uncorrected события имеют разную тяжесть. RAS объединяет механизмы надёжности, доступности и обслуживания; Machine Check — один из способов сообщить аппаратную ошибку.',
    'EDAC, сообщения ядра и BMC могут давать разные представления события. Важны время, счётчик, прирост, канал, DIMM и точность локализации платформы. SMBIOS с установленной ёмкостью не доказывает доступную ОС память; резерв прошивки, настройки, ограничения и неисправности требуют отдельного сравнения. Отсутствие счётчиков в госте не является нулём ошибок физической памяти.',
    'BMC сообщил рост corrected errors одного канала, в госте ошибок нет.',
    'ВМ может не получать физическую телеметрию. Сначала сверяют хост, топологию DIMM и доступные источники; чистый гостевой журнал не опровергает BMC.',
    'Раздели факты «DIMM установлен», «ОС использует память», «ECC работает», «ошибок за интервал не наблюдалось». Чем подтверждается каждый?',
    'Нельзя объявить DIMM неисправным только по одному неподтверждённому номеру слота. Нагрузочное испытание и перестановка модулей — отдельные аппаратные процедуры.')

add('pcie', 'Устройство, адреса и драйвер — отдельные этапы',
    'PCIe образует дерево двухточечных соединений от root complex через порты и switches. BDF идентифицирует функцию в текущем перечислении. Configuration space содержит идентификаторы и возможности; BAR запрашивает адресный ресурс для регистров или памяти устройства, не обязательно объём DRAM. Наличие функции до загрузки драйвера уже является отдельным фактом.',
    'Скорость зависит от поколения, числа линий, кодирования и накладных расходов. Link training может согласовать меньше линий, чем физически позволяет слот; bifurcation делит линии по поддерживаемой схеме. Максимальная возможность и фактический Link Status различаются. AER сообщает ошибки канала с разной тяжестью. IOMMU переводит DMA-адреса и помогает изоляции; группы отражают доступные границы изоляции топологии, а не произвольные пожелания оператора.',
    'Карта видна в lspci, link согласован x4, но дисков нет.',
    'Перечисление PCIe состоялось. Теперь проверяют драйвер, ресурсы BAR, прошивку карты и downstream-устройства; отсутствие дисков не означает отсутствие самой функции.',
    'Построй дерево для карты в райзере и сравни LnkCap с LnkSta. Какой дополнительный факт нужен, чтобы обвинить райзер в снижении ширины?',
    'Перепривязка live-драйвера и passthrough могут лишить хост диска или сети. В учебном чтении только наблюдают; аппаратные действия требуют отдельного окна и возврата.')

add('device-id', 'Метка модели не равна конкретному экземпляру',
    'Vendor/device ID описывают тип PCI-функции; subsystem ID уточняет исполнение. BDF показывает положение в текущем дереве. Серийный номер, WWN, MAC и UUID принадлежат разным объектам и могут быть виртуализированы, клонированы или отсутствовать. Идентичность устанавливают сочетанием устойчивого ID и физической/логической связи.',
    'Один адаптер может иметь несколько функций, несколько портов и собственный контроллер управления. Таблица драйверов связывает подходящий тип устройства с кодом, но загрузка модуля не гарантирует завершение probe. Версия прошивки и согласованная линия также относятся к конкретной функции и пути.',
    'Две одинаковые сетевые карты имеют одинаковые vendor/device ID, но разные MAC и слоты.',
    'Тип совпал, экземпляры разные. Выбор по одному идентификатору модели может затронуть не тот рабочий порт.',
    'Составь инвентарь «тип → экземпляр → слот → драйвер → используемый интерфейс». Какие поля изменятся при переносе карты в другой слот?',
    'Нельзя автоматически выполнять действие по первому совпадению модели. Перед изменением проверяют фактическую роль устройства и независимый доступ.')

add('bmc', 'Управление живёт отдельно от основной ОС',
    'BMC — управляющий компьютер с собственной прошивкой, сетью и учётными данными. Он может оставаться доступным при выключенной основной ОС. IPMI и Redfish предоставляют интерфейсы управления, SOL и удалённый экран — разные способы консольного доступа. Доступная BMC не доказывает, что основная ОС загрузилась; выключенная ОС не означает обесточенную плату.',
    'Датчик имеет тип, единицу, порог и место измерения. SEL хранит аппаратные события, но часы BMC могут расходиться с ОС и внешним мониторингом. Охлаждение включает входной воздух, вентиляторы, направление потока, загрязнение и тепловую нагрузку. После внезапного выключения сопоставляют SEL, предыдущий boot журнала ОС и питание/UPS; один источник не описывает всю последовательность.',
    'Под нагрузкой растёт температура входящего воздуха, затем BMC сообщает thermal shutdown; в ОС лишь обрыв журнала.',
    'ОС могла не успеть записать финальное событие. Общая последовательность поддерживает тепловую причину, но нужны проверка датчика и физического потока воздуха.',
    'Построй три линии времени с указанной погрешностью часов. Какие данные отличат потерю питания от штатного reboot?',
    'BMC относится к отдельной плоскости доступа. Управляющие пароли и интерфейсы не публикуют вместе с учебной страницей; команды power/reset не являются чтением телеметрии.')

add('power', 'Резерв считается по целому пути',
    'Два PSU могут обеспечивать резерв блока, если оставшийся способен нести нагрузку. Но общий удлинитель, ввод или UPS сохраняет единый отказ. N+1 описывает дополнительный элемент относительно требуемого числа; 2N — две полные мощности, однако физическая независимость зависит от подключения и переключения.',
    'Электрическая мощность, энергия и тепловыделение имеют разные единицы. В установившемся режиме почти вся потребляемая сервером электрическая мощность превращается в тепло. Мощности достаточно недостаточно: охлаждение должно отводить его с учётом направления воздуха и допустимых температур компонентов.',
    'Сервер потребляет 600 W; установлены два PSU по 800 W, оба подключены к одному отключившемуся PDU.',
    'Резерв PSU не спас от отказа общей точки питания. Номинальная мощность каждого блока отвечает на другой вопрос.',
    'Нарисуй два полностью независимых пути питания до ввода. Затем отметь общий охлаждающий контур и проверь, что он остаётся доменом отказа.',
    'Изъятие PSU и отключение ввода — аппаратное испытание. Расчёт и чтение датчиков не засчитывают его выполнение.')

add('uefi', 'До ядра работает своя среда',
    'После reset платформа должна подготовить ресурсы, найти загрузочный объект и передать управление. Legacy BIOS и UEFI имеют разные интерфейсы запуска. UEFI запускает подходящие PE/COFF-образы, предоставляет Boot Services и протоколы. EFI System Partition обычно содержит файловую систему FAT и загрузочные файлы; Boot#### и BootOrder указывают варианты запуска, а не гарантируют наличие и исправность файла.',
    'Device path описывает путь к устройству или файлу в модели UEFI. Shell позволяет исследовать отображения и запускать приложения, но fs0 не является постоянной идентичностью. EDK2 — реализация и набор средств разработки, а не сама спецификация UEFI. Приложение использует найденные протоколы; после ExitBootServices меняется доступность служб, часть Runtime Services может использоваться ОС по контракту.',
    'Файл .efi виден в Shell, но запуск отвергается.',
    'Файловая доступность доказана; совместимость архитектуры, формата и политика доверия ещё нет. Проверяют точную ошибку, образ и Secure Boot, а не форматируют USB.',
    'Объясни отдельно ESP, BootOrder, device path и исполняемый образ. Как проверить изменения на OVMF без записи прошивки физической платы?',
    'Записи NVRAM и файлы ESP влияют на загрузку. Сначала наблюдай; сохраняй конфигурацию гостя и независимую консоль. Успех OVMF не квалифицирует конкретную плату.')

add('secure-boot', 'Разрешённый образ и доверенная система',
    'Secure Boot проверяет допустимость загрузочных образов по политике платформы. PK, KEK, db и dbx имеют разные роли управления ключами, разрешениями и отзывами. Подписанный образ может быть разрешён, но подпись не доказывает отсутствие уязвимости. Отзыв может запретить ранее работавший файл. Проверка загрузочной цепочки отличается от measured boot, который фиксирует измерения.',
    'Firmware volume хранит модули прошивки и не равен разделу ESP на диске. Смена одного .efi не тождественна перепрошивке SPI. Контракт доверия требует идентичности издателя, допустимого образа, правильной архитектуры и актуальной политики; отключение проверки меняет этот контракт.',
    'После обновления списка отзывов старый подписанный загрузчик перестал запускаться.',
    'Наличие подписи не гарантирует разрешение текущей политикой. Нужно сопоставить точный файл и отзыв, а не считать неисправной файловую систему.',
    'Нарисуй цепочку доверия до ядра и отметь, что именно проверено на каждом шаге. Какие изменения можно безопасно исследовать только в отдельном OVMF-госте?',
    'Не очищай ключи и не отключай Secure Boot реальной машины как универсальный ремонт. Сначала сохрани сведения о политике и путь возврата.')

add('firmware-phases', 'Передача подготовленного состояния',
    'В типичной PI-платформе SEC создаёт ранние условия исполнения, PEI выполняет раннюю инициализацию и подготавливает память, DXE разворачивает драйверы и службы, BDS относится к выбору загрузки. HOB передаёт сведения от PEI к DXE. Это модель PI, а не обязательное описание каждой прошивки любой архитектуры. Option ROM и UEFI-драйвер устройства могут участвовать до запуска ОС, а драйвер Linux загружается позже.',
    'Прошивка передаёт ОС сведения о ресурсах и платформе через согласованные интерфейсы, включая ACPI. AML выполняется интерпретатором ОС в namespace ACPI; _OSI — запрос интерфейсной совместимости, не надёжное имя дистрибутива. SMM и Runtime Services имеют отдельные роли после старта ОС. Переменные NVRAM сохраняют часть состояния, поэтому обновление образа и сброс настроек — разные изменения.',
    'Контроллер виден в UEFI Shell, но Linux не привязал драйвер.',
    'Одна среда успешно перечислила устройство. Для другой нужно проверить ID, ресурсы, probe и совместимость; этот факт не доказывает дефект DXE.',
    'Расположи память, HOB, DXE-драйвер, BDS и ядро на временной схеме. Какие наблюдения позволяют поставить границу отказа между стадиями?',
    'Диаграмма фаз не является разрешением менять SPI-образ. Исследования модулей и сборки выполняются отдельно от аппаратной прошивки.')

add('acpi', 'Описание платформы должно совпадать с ресурсами',
    'ACPI предоставляет таблицы и исполняемые описания взаимодействия ОС с платформой. MADT описывает элементы прерываний и процессоров, SRAT — принадлежность ресурсов к близости NUMA, SLIT — относительные расстояния, DSDT/SSDT — определения namespace и методов. Наличие таблицы не гарантирует её корректность; ядро может отвергнуть часть сведений или применить обход.',
    'PCIe-устройство перечисляется по configuration space, но его BAR нуждается в адресном окне у всей цепочки мостов. Свободная RAM и доступное MMIO-пространство — не одно и то же. Прошивка и ОС могут по-разному распределять ресурсы; это требует сравнения дерева и ошибок. ACPI также описывает события и состояния питания; успешное чтение таблиц не доказывает правильные переходы сна или выключения.',
    'Функция PCIe видна, но журнал сообщает невозможность выделить BAR за мостом.',
    'Перечисление прошло, ресурс не выделен. Проверяют размер BAR, окна upstream-мостов и настройки платформы, а не только установку драйвера.',
    'Сопоставь SRAT с фактически видимыми NUMA-узлами. Где искать объяснение, если память установлена, но часть диапазонов ОС не использует?',
    'Извлечение таблиц — наблюдение, подмена AML и отключение ACPI меняют поведение платформы. Не используй такие изменения на рабочем хосте ради проверки гипотезы.')

add('firmware-update', 'Версия входит в матрицу совместимости',
    'У сервера есть отдельные BIOS/UEFI, BMC, прошивки контроллеров, NIC и накопителей. Их версии, ревизия платы, CPU и драйверы образуют матрицу совместимости. Capsule и фирменная утилита — способы доставки, не доказательства пригодности образа для конкретного экземпляра. До обновления нужны точная идентичность, release notes, инвентарь, настройки и проверенный recovery path.',
    'Обновление может сбросить параметры PCIe, bifurcation, загрузки или хранения. Потеря питания и прерывание асинхронной задачи имеют отдельные последствия; ответ «задача принята» не означает окончание. Откат версии может быть запрещён или не возвращать настройки и данные. Квалификация требует повторения исходных функциональных и нагрузочных проверок, а не только новой строки Version.',
    'После BIOS update два NVMe исчезли, а bifurcation вернулась к значению по умолчанию.',
    'Сначала сравни сохранённые настройки и PCIe-дерево. Версия изменилась одновременно с конфигурацией; причинность пока не отделена.',
    'Составь change record: исходные версии, целевой образ и hash, предпосылки, этапы, критерии stop/recovery и результаты после перезагрузки.',
    'В этом уроке анализируется план и инвентарь. Аппаратное обновление не засчитывается без испытания подходящего устройства и полного протокола.')

add('redfish', 'API управления не равен синхронной команде',
    'Redfish моделирует системы, managers, chassis и связанные ресурсы через HTTPS и JSON. Ресурс даёт свойства и ссылки, Action описывает доступное действие. Идентификаторы и пути конкретных Systems/Managers следует получать из ответов, а не придумывать. Аутентификация, сертификат сервера и право выполнить действие проверяются отдельно.',
    'HTTP 202 может вернуть задачу или monitor для отслеживания. Терминальное состояние задачи и фактическая версия ресурса нужны отдельно. ExtendedInfo и MessageId уточняют ошибку; строка HTTP success не заменяет содержимое ответа. Инвентарь может быть paginated и частично недоступен из-за прав.',
    'BMC вернул 202 на обновление, затем задача завершилась Exception.',
    'Был принят запрос, но изменение не завершено успешно. Скрипт обязан сохранить конечный статус и причину, а не объявить новую версию по факту первого ответа.',
    'Нарисуй цикл GET inventory → разрешённый Action → task monitor → terminal state → повторный GET. Какие шаги являются только чтением?',
    'Power и firmware actions меняют реальное оборудование. Учебный разбор использует предоставленный JSON; токены и пароли не включаются в отчёт.')

add('monitor', 'Наблюдение начинается с пользовательского вопроса',
    'Метрика агрегирует измерения во времени, журнал описывает события, trace связывает этапы запроса, событие изменения добавляет контекст. Prometheus опрашивает targets и хранит серии по имени и labels; Zabbix использует свою модель объектов и элементов данных. Dashboard показывает выбранные ряды, но не доказывает полноту наблюдения. Up относится к успешности scrape, а не ко всей услуге.',
    'Counter накапливает события и может сбрасываться, gauge описывает текущее значение; скорость счётчика требует учитывать reset. Каждая комбинация labels создаёт серию: user ID и request ID быстро увеличивают cardinality. Scrape interval и timeout ограничивают, что можно увидеть. SLI — измеряемый показатель услуги, SLO — цель для него. Датчики хоста, место ФС, inode и прикладной HTTP-путь дополняют друг друга.',
    'Rootfs заполнилась ночью; сбор метрик с агента продолжал отвечать, страница перестала сохранять заметку.',
    'Живой агент не подтверждал пользовательскую операцию записи. Нужны место/inodes, ошибка приложения и отдельная проверка сохранения.',
    'Спроектируй минимальный набор сигналов для заметки: запрос, сохранение, зависимость, ресурс и изменение конфигурации. Чем поможет каждый?',
    'Не добавляй секреты и неограниченные идентификаторы в labels. Отсутствие ряда может означать отказ сбора, а не нулевое значение.')

add('alert', 'Оповещение должно вести к действию',
    'Оповещение связывает условие с владельцем, срочностью и проверяемым действием. Порог ресурса может быть ранним сигналом, но не всегда означает пользовательский отказ. SLO задаёт допустимую долю плохих событий в выбранном окне, error budget — оставшийся запас. Burn rate показывает, насколько быстро он расходуется относительно допустимого темпа.',
    'Для временного SLO 99,9% за 30 дней бюджет недоступности равен 43,2 min. Для SLO по запросам бюджет считается по числу запросов, а не автоматически в минутах. Интервал scrape, окно условия и for-delay влияют на обнаружение; физическая причина могла возникнуть раньше первой метрики. Группировка и подавление уменьшают шум, но могут скрыть отдельный важный отказ.',
    'CPU 95%, пользовательский ответ в норме; через час CPU 20%, а все запросы записи получают ошибку.',
    'Один порог CPU не выражает качество услуги. Срочность определяют симптом и риск, а диагностику — дополнительные ресурсы и изменения.',
    'Напиши текст одного actionable alert: влияние, начало, цель проверки и ссылка на runbook. Какие условия предотвращают постоянные ложные вызовы?',
    'Процент без окна, определения плохого события и источника данных не является SLO. Учебный расчёт не доказывает реальную доступность сервиса.')

add('access', 'Кто входит и что ему разрешено',
    'Идентификация называет участника, аутентификация проверяет предъявленное доказательство, авторизация разрешает действие над объектом. SSH-клиент проверяет ключ хоста, сервер — способ входа пользователя: эти направления доверия различны. Закрытый ключ нельзя передавать серверу как пароль. Модель угроз называет активы, возможные действия противника и границы, на которых их ограничивают.',
    'Наименьшие права ограничивают область ошибки: отдельные пользователи служб, точечный sudo, capabilities вместо полного root там, где это уместно. SUID и мандатные политики меняют модель доступа сверх обычных прав. Сегментация ограничивает пути, аудит сохраняет действия с идентичностью и временем. Secret rotation требует замены и отзыва раскрытого значения; удаление его из текущего файла недостаточно. Hardening проверяют по ожидаемым разрешениям и запретам, а не количеству переключателей.',
    'Пользователь успешно вошёл по SSH, но не имеет права менять конфигурацию службы.',
    'Аутентификация сработала, авторизация отказала. Это может быть правильной политикой; выдача полного root для обхода ошибки не обоснована.',
    'Для ученика, службы и администратора составь матрицу чтения, записи и изменения запуска. Как подтвердить, что запрет действительно действует?',
    'Перед отключением пароля проверь новый вход по ключу в независимой сессии и доступ к консоли. Не закрывай единственный работающий путь управления.')

add('tls', 'Шифрование и проверка имени — разные свойства',
    'TLS устанавливает защищённый канал и проверяет участника по выбранной политике. Сертификат связывает ключ с именами и другими атрибутами; цепочка ведёт к доверенному корню. Для клиента важны SAN с нужным именем, срок, назначение, подпись и доступность промежуточных сертификатов. SNI сообщает серверу требуемое имя при выборе сертификата; HTTP Host относится уже к прикладному запросу.',
    'Собственный CA на стенде помогает понять выдачу и доверие, но требует защиты закрытого ключа и явного добавления корня только в учебную область. Продление сертификата, загрузка нового файла службой и фактический сертификат на сокете — разные события. Проверка с отключённой валидацией может показать транспорт, но не подтверждает правильное доверие.',
    'Файл сертификата обновлён, а удалённый клиент всё ещё видит истёкший сертификат.',
    'Возможны неприменённая конфигурация, другой endpoint или промежуточный узел. Сравни фактически предъявленный fingerprint с файлом и проверяй нужное имя.',
    'Раздели отказы: неверный SAN, неизвестный CA, истёкший срок, неготовый слушатель. Какая проверка различает их без отключения валидации?',
    'Не распространяй учебный CA на рабочие устройства и не публикуй закрытые ключи. Работающий TCP ещё не означает корректный TLS.')

add('time', 'Часы отвечают на разные вопросы',
    'RTC хранит время между запусками, realtime даёт календарные отметки, monotonic измеряет интервалы без обычных переводов стеновых часов. Частота локального источника может дрейфовать. NTP оценивает смещение и задержку обмена с источниками, но асимметрия пути ограничивает точность. Slew плавно подстраивает ход, step скачком меняет отметку; политика зависит от клиента и этапа работы.',
    'UTC и часовой пояс — представления календарного времени; смена пояса не исправляет физическое смещение часов. Работающий daemon не доказывает синхронизацию: нужны источник, reachability, offset и состояние. Для высокой точности могут потребоваться PTP и аппаратные timestamp, причём вся цепочка оборудования должна поддерживать требуемую модель. Локальный порядок событий уточняют boot ID и монотонными отметками, межмашинный — также причинными связями запросов.',
    'Сервис запущен, но все источники времени недоступны, offset продолжает расти.',
    'Факт наличия процесса не равен контролируемой погрешности. Сначала проверяют источник и доступность, не меняя часовой пояс.',
    'Выбери часы для длительности запроса, сертификата и корреляции журналов. Что произойдёт с разностью realtime при переводе назад?',
    'В гостевой практике часы не меняются у общего хоста. Коррекция реального времени может влиять на базы, TLS и задания по расписанию.')

add('duration', 'Отметка имеет погрешность',
    'Сопоставляя два журнала, сохраняй исходные отметки, часовой пояс, точность и известное смещение. Если часы A спешат на 5 s, для сравнения их отметку уменьшают на 5 s. Интервал возможного времени расширяется на неопределённость синхронизации и самого измерения. Близкие отметки разных машин могут не задавать однозначный порядок.',
    'Причинная связь «ответ следует за запросом» иногда надёжнее календарного порядка. Correlation ID связывает события, но должен создаваться и передаваться корректно. Длительность локальной операции измеряют monotonic; временная линия инцидента сохраняет и факты, и выбранные поправки, не переписывая исходный журнал.',
    'A записал запрос в 12:00:05, B — приём в 12:00:02. A спешит на 4 s, B синхронизирован с погрешностью до 1 s.',
    'Исправленная отметка A — 12:00:01. Отрицательная «задержка» исходных строк была артефактом часов; точность вывода всё ещё ограничена погрешностью B.',
    'Построй исходную и приведённую линии времени для трёх узлов. Отметь пары событий, порядок которых нельзя установить.',
    'Не подгоняй смещения под желаемую причину. Неизвестная погрешность должна оставаться неизвестной, а не превращаться в ноль.')

add('availability', 'Модель отказа важнее красивого процента',
    'Доступность — доля хорошего времени или событий в явно определённой области. Для независимых последовательных компонентов A=A₁A₂: услуге нужны оба. Для независимых параллельных вариантов, каждый из которых способен обслужить нагрузку, A=1−(1−A₁)(1−A₂). Эти формулы не описывают общие питание, программную ошибку или ошибку переключения автоматически.',
    'Домен отказа объединяет компоненты, которые может выключить одно событие. N+1 и 2N задают резерв мощности, но требуют проверенного переключения и достаточной оставшейся ёмкости. Деградация может сохранить чтение, но потерять запись или время ответа: определение доступности должно это отражать. Реальное испытание резерва выявляет скрытые зависимости лучше одного расчёта.',
    'Две ветви по 99% при независимости дают 99,99%; обе зависят от общего компонента с 99% доступности.',
    'С учётом независимого общего компонента модель даёт 0,99×0,9999=0,989901, то есть 98,9901%. Общий компонент ограничил весь результат.',
    'Нарисуй домены отказа страницы с заметками: DNS, питание, сеть, приложение, диск, operator. Какие предположения нужны для перемножения?',
    'Модель не доказывает достигнутый SLO. Указывай зависимость отказов, окно, нагрузку и то, какие режимы услуги считаются хорошими.')

add('recovery-time', 'Восстановление состоит из этапов',
    'MTBF — модель среднего интервала между отказами ремонтируемой системы, MTTR требует явного определения начала и конца восстановления. При простой стационарной двухсостоянийной модели A=MTBF/(MTBF+MTTR). Это приближение, а не закон для любой системы с зависимыми отказами и неполной статистикой.',
    'Время восстановления раскладывается на обнаружение, оценку, принятие решения, выполнение и подтверждение пользовательского результата. Ускорение перезапуска не поможет, если час уходит на обнаружение или поиск ключа. RTO — цель для услуги, её достижение нужно измерить на полном цикле.',
    'Обнаружение заняло 20 min, решение 10 min, восстановление файлов 5 min, приёмка 5 min.',
    'Полный цикл — 40 min. Отчёт «восстановили за 5 минут» измерил только копирование и пропустил основные задержки.',
    'Пересчитай результат, если автоматическая проверка снизит обнаружение до 2 min. Какой следующий этап выгоднее улучшать?',
    'Среднее не задаёт худший случай. Отдельно сохраняй разброс и сложные отказы; лабораторная скорость не обещает production RTO.')

add('incident', 'Работа с неполной информацией',
    'Инцидент — нарушение услуги, требующее координированного восстановления; задача по улучшению может не быть инцидентом. Уровень задают влиянием и срочностью, а не эмоциональной формулировкой. Дежурный должен уметь установить границу, безопасно действовать, передать контекст и привлечь нужного владельца. Оповещение без получателя и следующего действия создаёт эксплуатационный долг.',
    'Карточка инцидента хранит симптом, затронутый путь, время, исходные факты, гипотезы, действия и результаты. Хронология из журналов надёжнее воспоминаний. Runbook описывает условия применимости, диагностику, ограниченные действия, stop conditions, откат и приёмку. Он становится продуктом только после проверки на соответствующей ситуации.',
    'Ночью пришёл alert «диск», но не указан хост и все предыдущие действия находятся в личной переписке.',
    'Нужно сначала определить объект и влияние, а не повторить чью-то команду по памяти. Потеря контекста увеличивает время восстановления.',
    'На незнакомом отчёте заполни первые пять строк карточки без изменений системы. Какую одну проверку ты выберешь для разделения двух гипотез?',
    'Не меняй сразу несколько слоёв. Быстрое восстановление допустимо до полного объяснения причины, но факт вмешательства и его цена должны быть сохранены.')

add('incident-close', 'Ответ вернулся — работа ещё требует приёмки',
    'Восстановление услуги, установление причины и предотвращение повторения — разные результаты. После вмешательства проверяют пользовательскую операцию, данные, соседние пути и устойчивость. Утверждение о причине должно объяснять наблюдения и иметь проверяемый механизм, а не только совпадение «после перезагрузки заработало».',
    'Разбор без поиска виноватых исследует условия, в которых решение выглядело разумным: видимость, инструменты, ограничения и права. Улучшение получает владельца, срок и критерий проверки. Изменение runbook, резервного пути или сигнала полезно, если его проверили на повторном случае; обещание «быть внимательнее» не меняет систему.',
    'После рестарта запись заметок работает, но накопитель снова заполняется тем же временным файлом.',
    'Услуга восстановлена временно; механизм роста не устранён. Закрытие должно отдельно отметить временное действие и работу по причине.',
    'Составь завершение карточки: что восстановлено, чем доказано, что неизвестно, какое изменение предотвратит повтор и как его испытают.',
    'Не заполняй пробелы хронологии правдоподобными догадками. Неподтверждённая причина остаётся гипотезой.')

add('migration', 'Перенос имеет границу записи',
    'Миграция включает инвентарь, подготовку целевого состояния, перенос данных, переключение, проверку и выдержку до вывода источника. Окно остановки упрощает согласованность ценой недоступности. Поэтапный перенос уменьшает область изменения, но требует совместимости старого и нового состояния. Репликация и копирование без правила владельца записи могут создать два расходящихся источника истины.',
    'DNS TTL влияет на кеши, а не мгновенно переключает всех клиентов и открытые соединения. После переключения проверяют чтение, запись, фоновые задачи, права и полный путь клиента. Откат адреса не возвращает автоматически записи, сделанные на новой базе. До изменения определяют точку, после которой простой возврат уже небезопасен, и отдельную процедуру согласования данных.',
    'Часть клиентов по DNS пишет в старую базу, часть — в новую; синхронизация была остановлена до переключения.',
    'Появились две версии истины. Возврат DNS сам по себе не объединит данные; сначала нужно остановить расхождение и установить фактические записи.',
    'Предложи план с одним владельцем записи и отдельной проверкой переключения. Где будут контрольная точка, критерий остановки и решение об откате?',
    'Не удаляй источник после первого успешного запроса. Срок выдержки и ответственность за данные задают до миграции.')

add('decommission', 'Обратимость нужно испытать',
    'Изменение — гипотеза об улучшении с предпосылками и проверяемым исходом. Обратимость зависит от данных и внешних эффектов, не только от наличия старого файла. Точка невозврата возникает, когда совместимый возврат больше не обеспечен: например, после необратимой миграции формата или уничтожения единственной копии ключа.',
    'Вывод из эксплуатации начинается с владельца, зависимостей, срока хранения и оснований сохранить данные. Затем прекращают новые обращения, проверяют отсутствие нужного трафика, сохраняют необходимое, отзывают доступы и обновляют инвентарь. Утилизация носителя использует подходящую утверждённую процедуру с подтверждением, а не простое удаление каталога.',
    'ВМ выключили, но её учётная запись и backup credentials продолжают действовать.',
    'Ресурс перестал выполнять работу, однако часть доступа осталась. Вывод затрагивает идентичность и секреты вместе с вычислительным объектом.',
    'Составь обратимую фазу карантина и отдельную необратимую фазу уничтожения. Какое доказательство позволит перейти между ними?',
    'Этот урок требует плана и исследования данных. Удаление чужих ресурсов и носителей не становится разрешённым от наличия команды в учебнике.')

add('baseline', 'Эталон должен проверять услугу',
    'Итоговая система включает схему, адресный план, маршрутизируемые сегменты, виртуальные ресурсы, хранение, приложение, наблюдение и автоматизацию. Baseline хранит версии, конфигурацию и проверяемые пользовательские результаты. Он позволяет сравнить исходное состояние с отказом и возвратом, но сам не объясняет причину различия.',
    'Серия отказов проверяет разные границы: DNS при живом IP-пути; неверный VLAN; loopback вместо сетевого слушателя; fstab и загрузку; degraded RAID/ZFS; потерю пути multipath; запись в несмонтированный каталог; удалённый открытый лог; Running без готовности; задержки I/O; drift; PCIe и регрессию прошивки. Последние аппаратные случаи допускают анализ наблюдений, но выполнение на железе учитывается отдельно.',
    'После исправления mount HTTP 200 вернулся, но заметка относится к пустой новой файловой системе.',
    'Протокол отвечает, данные не восстановлены. Приёмка должна включать контрольное содержимое и идентичность источника, а не только статус.',
    'Подготовь baseline и выбери неизвестный заранее отказ. Оцени решение по локализации, доказательству механизма, безопасности, пользовательской проверке и предотвращению.',
    'Счёт тестов и отчёт с hash не заменяют самостоятельность и перенос навыка. Финальная приёмка требует новой задачи после перерыва и честного разделения данных, ВМ и оборудования.')

add('unknown-incident', 'Перенос навыка начинается без готового диагноза',
    'В незнакомом случае известны симптом и условия, но не причина. Сначала восстанови модель пути заметки и выбери границу с различающими предсказаниями. Сохраняй отвергнутые гипотезы с причиной отказа от них, чтобы не повторять одни и те же действия. Отсутствие команды из знакомого урока не мешает применить тот же метод.',
    'Решение оценивается по наблюдаемому результату и обоснованности действия. Верное исправление случайным перебором не равно устойчивому навыку. Подтверждение после изменения должно проверять исходный симптом, соседний допустимый путь и сохранность данных. После новой модификации системы прежний отчёт описывает только прошлое состояние.',
    'Клиент читает старую заметку, сервер возвращает новую, ошибок транспорта нет.',
    'Нужна гипотеза о различии пути или состояния: кеш, другой endpoint, другое имя. «Перезапустить всё» не разделяет эти варианты.',
    'Назови две проверки с разными предсказаниями. Через несколько дней повтори на другом варианте, не заглядывая в прежнюю последовательность команд.',
    'Автоматически подтверждается только проверяемая часть. Собственное объяснение сохраняется для обсуждения; скрипт не объявляет его понятым по длине текста.')
